function villageRows(lines) {
  return lines.map((line) => {
    const [yymm, cc, cc_name, rcode, rcode_name, tt, tt_name, mm, mm_name, ...counts] = line.split("|").map((s) => s.trim());
    const [male, female, total, house] = counts.map((s) => Number(s.replace(/,/g, "")));
    return { yymm, cc, cc_name, rcode, rcode_name, tt, tt_name, mm, mm_name, male, female, total, house };
  });
}

